diff --git a/src/db/pool.ts b/src/db/pool.ts
index 7446fda..9bfc823 100644
--- a/src/db/pool.ts
+++ b/src/db/pool.ts
@@ -1,3 +1,77 @@
-import { Pool } from "pg";
+import { Pool, QueryResult } from "pg";

-export const pool = new Pool({ connectionString: process.env.DATABASE_URL });
+const pool = new Pool({ connectionString: process.env.DATABASE_URL });
+
+const COLUMN_CACHE = new Map<string, Set<string>>();
+
+const loadTableColumns = async (tableName: string): Promise<Set<string>> => {
+  if (COLUMN_CACHE.has(tableName)) {
+    return COLUMN_CACHE.get(tableName)!;
+  }
+
+  const result = await pool.query(
+    `SELECT column_name FROM information_schema.columns
+     WHERE table_schema = 'public' AND table_name = $1`,
+    [tableName]
+  );
+
+  const columns = new Set(result.rows.map((r) => r.column_name));
+  COLUMN_CACHE.set(tableName, columns);
+  return columns;
+};
+
+const extractTableReferences = (sql: string): string[] => {
+  const matches = sql.match(/FROM\s+(\w+)|INTO\s+(\w+)|UPDATE\s+(\w+)|INSERT\s+INTO\s+(\w+)/gi);
+  const tables = new Set<string>();
+  if (matches) {
+    matches.forEach((match) => {
+      const table = match.split(/\s+/).pop()?.toLowerCase();
+      if (table) tables.add(table);
+    });
+  }
+  return Array.from(tables);
+};
+
+const extractColumnReferences = (sql: string): string[] => {
+  const normalized = sql.replace(/\$\d+/g, "?");
+  const simpleColumns = normalized.match(/\b([a-z_]\w*)\s*=/gi) || [];
+  const selectColumns = normalized.match(/SELECT\s+([\w\s,."*]+)\s+FROM/i) || [];
+
+  const columns = new Set<string>();
+  simpleColumns.forEach((match) => {
+    const col = match.replace(/[=\s]/g, "").toLowerCase();
+    if (col && col !== "select" && col !== "from" && col !== "where") {
+      columns.add(col);
+    }
+  });
+
+  if (selectColumns[1]) {
+    selectColumns[1].split(",").forEach((col) => {
+      const trimmed = col.trim().toLowerCase().split(/\s+/).pop()?.replace(/["']/g, "");
+      if (trimmed && trimmed !== "*") columns.add(trimmed);
+    });
+  }
+
+  return Array.from(columns).filter((c) => c.length > 0);
+};
+
+export { pool };
+
+export const query = async <T = any>(text: string, values?: any[]): Promise<QueryResult<T>> => {
+  const tables = extractTableReferences(text);
+  const columns = extractColumnReferences(text);
+
+  for (const tableName of tables) {
+    const tableColumns = await loadTableColumns(tableName);
+    for (const col of columns) {
+      if (!tableColumns.has(col) && col !== "*") {
+        throw new Error(
+          `Query references non-existent column "${col}" on table "${tableName}". ` +
+          `Available columns: ${Array.from(tableColumns).sort().join(", ")}`
+        );
+      }
+    }
+  }
+
+  return pool.query<T>(text, values);
+};
